namespace Shop.SqlTests;
public sealed class CmsBlogPostSqlTests:IAsyncLifetime
{
    private readonly SqlFixture sql=new();private WebApplicationFactory<Program>? auth;public Task InitializeAsync()=>sql.InitializeAsync();public async Task DisposeAsync(){auth?.Dispose();await sql.DisposeAsync();}
    private static string Id()=>Guid.NewGuid().ToString("N");private static string S(JsonNode n,string key)=>n[key]!.GetValue<string>();
    private static CmsBlogContent Content(string title="SYNTHETIC BLOG QA",string tag="guide")=>new(new(new(title,"محتوای ساختگی نرم‌افزار؛ سیاست تجاری نیست",[new(Id(),"Text","All",Heading:"",Text:"متن سادهٔ نمونه 🎮")]),new("SYNTHETIC ARTICLE","Synthetic sample only",[new(Id(),"Text","All",Heading:"",Text:"Sample text only")])),"Organization","تیم ساختگی نرم‌افزار","Synthetic software team",null,null,null,[new("a-b","الف","A hyphen B"),new("ab","الف دوم","AB"),new(tag,"برچسب نمونه","Sample tag")]);
    private static async Task<JsonNode> Read(HttpResponseMessage response){using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: "+System.Text.RegularExpressions.Regex.Replace(raw,"(?i)Bearer [A-Za-z0-9._~-]+","Bearer [REDACTED-SYNTHETIC-QA-TOKEN]"));Assert.Contains("no-store",response.Headers.CacheControl!.ToString());var req=response.RequestMessage!;var path=req.RequestUri!.PathAndQuery;if(path.StartsWith("/api/admin/blog-posts",StringComparison.Ordinal))Assert.Contains("private",response.Headers.CacheControl.ToString());if(path.StartsWith("/api/admin/blog-posts",StringComparison.Ordinal)||path.StartsWith("/api/content/blog",StringComparison.Ordinal)){Assert.Contains("noindex",response.Headers.GetValues("X-Robots-Tag").Single());if(Environment.GetEnvironmentVariable("SHOP_CMS_BLOG_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);var id=Id();JsonNode? body=req.Options.TryGetValue(new HttpRequestOptionsKey<string>("SyntheticBlogBody"),out var posted)?JsonNode.Parse(posted):null;await File.WriteAllTextAsync(System.IO.Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(System.IO.Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{syntheticQaOnly=true,actualSqlHttpResponse=true,status=(int)response.StatusCode,method=req.Method.Method,path,requestBody=body,blogSchema=response.Headers.TryGetValues("X-Sayman-Blog",out var schema)?schema.Single():null}));}}return JsonNode.Parse(raw)!;}}
    private async Task<HttpClient> Staff(string role="ContentManager"){await using var scope=sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="blogqa"+Id();var u=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true,RequireMfa=true};Assert.True((await users.CreateAsync(u,sql.Password)).Succeeded);Assert.True((await users.AddToRoleAsync(u,role)).Succeeded);var c=(auth??=sql.Factory.WithWebHostBuilder(_=>{})).CreateClient(new(){HandleCookies=false});c.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3173");c.DefaultRequestHeaders.Add("X-Sayman-Client","admin");c.DefaultRequestHeaders.Add("X-Sayman-Admin","1");var p=await Read(await c.PostAsJsonAsync("/api/auth/password",new{Identifier=name,Password=sql.Password}));c.DefaultRequestHeaders.Authorization=new("Bearer",S(p,"accessToken"));var setup=await Read(await c.PostAsJsonAsync("/api/auth/mfa/setup",new{}));c.DefaultRequestHeaders.Authorization=new("Bearer",S(setup,"accessToken"));var signed=await Read(await c.PostAsJsonAsync("/api/auth/mfa/verify",new{Code=Totp.Code(S(setup,"secret"),DateTimeOffset.UtcNow.ToUnixTimeSeconds()/30)}));c.DefaultRequestHeaders.Authorization=new("Bearer",S(signed,"accessToken"));return c;}
    private static string Path(JsonNode p)=>"/api/admin/blog-posts/"+S(p,"postId");
    private static async Task<JsonNode> Send(HttpClient c,string path,CmsBlogPostWrite body){if(body.Action!="Create")await Read(await c.GetAsync(path[..path.LastIndexOf("/commands/",StringComparison.Ordinal)]));var raw=JsonSerializer.Serialize(body,CmsBlogPostRules.Json);var request=new HttpRequestMessage(HttpMethod.Post,path){Content=new StringContent(raw,System.Text.Encoding.UTF8,"application/json")};request.Options.Set(new HttpRequestOptionsKey<string>("SyntheticBlogBody"),raw);return await Read(await c.SendAsync(request));}
    private static Task<JsonNode> Create(HttpClient c,bool demo=true,string? slug=null,CmsBlogContent? content=null)=>Send(c,"/api/admin/blog-posts/commands/"+Id(),new("Create",Slug:slug??"qa-"+Id(),IsDemo:demo,Content:content??Content()));
    private static Task<JsonNode> Write(HttpClient c,JsonNode p,string action,CmsBlogContent? content=null,string? restore=null,string? command=null)=>Send(c,Path(p)+"/commands/"+(command??Id()),new(action,S(p,"version"),Content:content,RestoreRevisionId:restore,Confirmed:action!="Save"));
    [Fact]public async Task DraftPublishSaveRestoreAndUnpublishKeepPublicMetadataAndFirstPublicationSeparate()
    {
        using var staff=await Staff();using var anon=sql.Factory.CreateClient(new(){HandleCookies=false});var draft=Content();var p=await Create(staff,content:draft);var route="/api/content/blog/fa/"+S(p,"slug");using(var hidden=await anon.GetAsync(route))Assert.Equal(HttpStatusCode.NotFound,hidden.StatusCode);p=await Write(staff,p,"Publish");var original=S(p,"revisionId");var published=await Read(await anon.GetAsync(route));Assert.True(published["isDemo"]!.GetValue<bool>());Assert.Equal(draft.Body.Fa.Title,S(published,"title"));Assert.Equal("Organization",S(published,"authorKind"));Assert.Equal(draft.BylineFa,S(published,"byline"));Assert.Equal(3,published["tags"]!.AsArray().Count);Assert.DoesNotContain("draftHash",published.ToJsonString());Assert.DoesNotContain("createdBy",published.ToJsonString());var first=S(published,"firstPublishedAt");var next=draft with{BylineFa="نام عمومی جدید",BylineEn="New public byline",Body=draft.Body with{Fa=draft.Body.Fa with{Title="پیش‌نویس جدید"}}};p=await Write(staff,p,"Save",next);Assert.Equal(draft.BylineFa,S(await Read(await anon.GetAsync(route)),"byline"));p=await Write(staff,p,"Publish");Assert.Equal(next.BylineFa,S(await Read(await anon.GetAsync(route)),"byline"));p=await Write(staff,p,"Unpublish");using(var hidden=await anon.GetAsync(route))Assert.Equal(HttpStatusCode.NotFound,hidden.StatusCode);p=await Write(staff,p,"Restore",restore:original);var restored=await Read(await anon.GetAsync(route));Assert.Equal(first,S(restored,"firstPublishedAt"));Assert.Equal(draft.BylineFa,S(restored,"byline"));Assert.NotEqual(original,S(restored,"revisionId"));var detail=await Read(await staff.GetAsync(Path(p)));Assert.Equal(next.BylineFa,S(detail["draft"]!,"bylineFa"));Assert.Equal(draft.BylineFa,S(detail["published"]!,"bylineFa"));Assert.Equal(4,(await Read(await staff.GetAsync(Path(p)+"/history")))["items"]!.AsArray().Count);var english=await Read(await anon.GetAsync(route.Replace("/fa/","/en/")));Assert.Equal(draft.BylineEn,S(english,"byline"));
    }
    [Fact]public async Task ReplayCasActorReceiptsAndPermissionsCannotOverwriteOrPublishForeignCommands()
    {
        using var staff=await Staff();using var other=await Staff();using var inventory=await Staff("InventoryManager");using var anon=sql.Factory.CreateClient(new(){HandleCookies=false});var p=await Create(staff);var command=Id();var input=new CmsBlogPostWrite("Publish",S(p,"version"),Confirmed:true);var first=await Send(staff,Path(p)+"/commands/"+command,input);var replay=await Send(staff,Path(p)+"/commands/"+command,input);Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(S(first,"revisionId"),S(replay,"revisionId"));await Read(await staff.GetAsync(Path(p)+"/commands/"+command));using(var foreign=await other.GetAsync(Path(p)+"/commands/"+command))Assert.Equal(HttpStatusCode.NotFound,foreign.StatusCode);using(var denied=await anon.GetAsync(Path(p)))Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);using(var denied=await inventory.GetAsync(Path(p)))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);using(var stale=await staff.PostAsJsonAsync(Path(p)+"/commands/"+Id(),input))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);var saved=await Write(staff,first,"Save",Content("SYNTHETIC UPDATED DRAFT"));var race=await Task.WhenAll(staff.PostAsJsonAsync(Path(p)+"/commands/"+Id(),new CmsBlogPostWrite("Publish",S(saved,"version"),Confirmed:true)),staff.PostAsJsonAsync(Path(p)+"/commands/"+Id(),new CmsBlogPostWrite("Publish",S(saved,"version"),Confirmed:true)));Assert.Single(race,r=>r.IsSuccessStatusCode);Assert.Single(race,r=>r.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)r.Dispose();await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Equal(2,await scope.ServiceProvider.GetRequiredService<CmsDbContext>().BlogPostRevisions.CountAsync());
    }
    [Fact]public async Task AuditFailureRollsBackPublicationTagsFirstDateAndReceiptBeforeRetry()
    {
        using var staff=await Staff();var p=await Create(staff);var command=Id();var input=new CmsBlogPostWrite("Publish",S(p,"version"),Confirmed:true);await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityDbContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_BlogAudit CHECK ([Action]<>'CMS_BLOG_POST_PUBLISH')");try{using var failed=await staff.PostAsJsonAsync(Path(p)+"/commands/"+command,input);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityDbContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_BlogAudit");}var head=await Read(await staff.GetAsync(Path(p)));Assert.Equal(S(p,"version"),S(head,"version"));Assert.Null(head["firstPublishedAt"]);Assert.Null(head["publishedRevisionId"]);await using(var check=sql.Factory.Services.CreateAsyncScope()){var db=check.ServiceProvider.GetRequiredService<CmsDbContext>();Assert.Equal(0,await db.BlogPostRevisions.CountAsync());Assert.Equal(0,await db.BlogRevisionTags.CountAsync());Assert.Equal(1,await db.BlogPostCommands.CountAsync());}await Send(staff,Path(p)+"/commands/"+command,input);await using var final=sql.Factory.Services.CreateAsyncScope();Assert.Equal(3,await final.ServiceProvider.GetRequiredService<CmsDbContext>().BlogRevisionTags.CountAsync());Assert.Equal(1,await final.ServiceProvider.GetRequiredService<IdentityDbContext>().Audit.CountAsync(x=>x.Action=="CMS_BLOG_POST_PUBLISH"));
    }
    [Fact]public async Task RelationalTagTamperHistoryGuardsOwnedRevisionFkAndDownCannotHideCorruption()
    {
        using var staff=await Staff();using var anon=sql.Factory.CreateClient(new(){HandleCookies=false});var p=await Write(staff,await Create(staff),"Publish");var q=await Write(staff,await Create(staff),"Publish");await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CmsDbContext>();Assert.False(db.Database.HasPendingModelChanges());var down=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.GetService<IMigrator>().MigrateAsync(db.Database.GetMigrations().Where(x=>!x.EndsWith("_VersionedBlogPosts",StringComparison.Ordinal)).Last()));Assert.Equal(51000,down.Number);var tag=await db.BlogRevisionTags.FirstAsync();db.Remove(tag);Assert.Equal("cms_blog_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();var head=await db.BlogPosts.SingleAsync(x=>x.Id==S(p,"postId"));head.FirstPublishedAt=head.FirstPublishedAt!.Value.AddTicks(-1);Assert.Equal("cms_blog_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [cms].[BlogPosts] SET [PublishedRevisionId]={S(q,"revisionId")} WHERE [Id]={S(p,"postId")}"));await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [cms].[BlogRevisionTags] SET [NameEn]={"CORRUPT SYNTHETIC TAG"} WHERE [RevisionId]={S(p,"revisionId")} AND [Slug]={"a-b"}");using(var corrupt=await anon.GetAsync("/api/content/blog/fa/"+S(p,"slug")))Assert.Equal(HttpStatusCode.ServiceUnavailable,corrupt.StatusCode);using(var restore=await staff.PostAsJsonAsync(Path(p)+"/commands/"+Id(),new CmsBlogPostWrite("Restore",S(p,"version"),RestoreRevisionId:S(p,"revisionId"),Confirmed:true)))Assert.Equal(HttpStatusCode.ServiceUnavailable,restore.StatusCode);Assert.Equal(2,await db.BlogPostRevisions.CountAsync());
    }
    private sealed class FixedClock(DateTimeOffset now):TimeProvider{public override DateTimeOffset GetUtcNow()=>now;}
    [Fact]public async Task PublicListingIsBoundedFilterAndLocaleScopedAndDoesNotAdmitLaterFirstPublications()
    {
        using var staff=await Staff();using var anon=sql.Factory.CreateClient(new(){HandleCookies=false});for(var i=0;i<21;i++)await Write(staff,await Create(staff,false,"qa-article-"+i.ToString("D2"),Content("SYNTHETIC "+i,i%2==0?"guide":"news")),"Publish");var first=await Read(await anon.GetAsync("/api/content/blog/fa"));Assert.Equal(20,first["items"]!.AsArray().Count);var cursor=S(first,"nextCursor");await Write(staff,await Create(staff,false,"qa-later-publication"),"Publish");var second=await Read(await anon.GetAsync("/api/content/blog/fa?cursor="+cursor));Assert.Single(second["items"]!.AsArray());Assert.Null(second["nextCursor"]);var ids=first["items"]!.AsArray().Concat(second["items"]!.AsArray()).Select(x=>S(x!,"id")).ToArray();Assert.Equal(21,ids.Distinct().Count());Assert.DoesNotContain(second["items"]!.AsArray(),x=>S(x!,"slug")=="qa-later-publication");var filter=await Read(await anon.GetAsync("/api/content/blog/en?tag=news"));Assert.Equal(10,filter["items"]!.AsArray().Count);foreach(var item in filter["items"]!.AsArray())Assert.Contains(item!["tags"]!.AsArray(),t=>S(t!,"slug")=="news");foreach(var path in new[]{"/api/content/blog/en?cursor="+cursor,"/api/content/blog/fa?tag=news&cursor="+cursor,"/api/content/blog/fa?tag=guide&tag=news","/api/content/blog/fa?limit=99"}){using var bad=await anon.GetAsync(path);Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);}await using var expired=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(s=>s.AddSingleton<TimeProvider>(new FixedClock(DateTimeOffset.UtcNow.AddMinutes(16)))));using var expiredClient=expired.CreateClient(new(){HandleCookies=false});using var late=await expiredClient.GetAsync("/api/content/blog/fa?cursor="+cursor);Assert.Equal(HttpStatusCode.Conflict,late.StatusCode);
    }
    [Fact]public async Task SamplesAreExplicitAndUnavailableToProductionReadersWithoutChangingStaticCmsPages()
    {
        using var staff=await Staff();var demo=await Write(staff,await Create(staff,true),"Publish");var real=await Write(staff,await Create(staff,false),"Publish");await using var scope=sql.Factory.Services.CreateAsyncScope();var sp=scope.ServiceProvider;var db=sp.GetRequiredService<CmsDbContext>();var production=new CmsBlogPostService(db,false,sp.GetRequiredService<TimeProvider>(),sp.GetRequiredService<ICmsBlogCursorProtection>());Assert.Equal("not_found",(await Assert.ThrowsAsync<BusinessException>(()=>production.PublicAsync(S(demo,"slug"),"fa",CancellationToken.None))).Code);Assert.Equal(S(real,"slug"),(await production.PublicAsync(S(real,"slug"),"en",CancellationToken.None)).Slug);Assert.Single((await production.PublicListAsync("fa",null,null,CancellationToken.None)).Items);Assert.Equal(0,await db.Pages.CountAsync());Assert.Equal(0,await db.PageRevisions.CountAsync());Assert.Equal(0,await db.PageCommands.CountAsync());
    }
    [Fact]public async Task NoopSaveAtTheSameClockStillRotatesVersionWithoutRewritingFirstPublication()
    {
        using var original=await Staff();var when=DateTimeOffset.UtcNow;await using var fixedFactory=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(s=>s.AddSingleton<TimeProvider>(new FixedClock(when))));using var client=fixedFactory.CreateClient(new(){HandleCookies=false});foreach(var header in original.DefaultRequestHeaders)client.DefaultRequestHeaders.TryAddWithoutValidation(header.Key,header.Value);var content=Content();var create=await Create(client,content:content);var save=await Write(client,create,"Save",content);Assert.NotEqual(S(create,"version"),S(save,"version"));Assert.Equal(S(create,"draftHash"),S(save,"draftHash"));var published=await Write(client,save,"Publish");var before=await Read(await client.GetAsync(Path(published)));var again=await Write(client,published,"Save",content);Assert.NotEqual(S(published,"version"),S(again,"version"));var after=await Read(await client.GetAsync(Path(again)));Assert.Equal(S(before,"firstPublishedAt"),S(after,"firstPublishedAt"));Assert.Equal(S(before,"draftHash"),S(after,"draftHash"));Assert.Equal(S(before,"publishedRevisionId"),S(after,"publishedRevisionId"));
    }

    [Fact]public async Task BlogSitemapExcludesDraftSamplesAndUnpublishedPostsAndTracksPublicationInsteadOfDraftSave()
    {
        using var staff=await Staff();using var anon=sql.Factory.CreateClient(new(){HandleCookies=false});var live=await Write(staff,await Create(staff,false),"Publish");await Write(staff,await Create(staff,true),"Publish");await Create(staff,false);var closed=await Write(staff,await Create(staff,false),"Publish");await Write(staff,closed,"Unpublish");var published=await Read(await anon.GetAsync("/api/content/blog/fa/"+S(live,"slug")));await Write(staff,live,"Save",Content("SYNTHETIC DRAFT MUST NOT CHANGE SITEMAP"));await using var scope=sql.Factory.Services.CreateAsyncScope();var service=scope.ServiceProvider.GetRequiredService<CmsBlogSitemapService>();Assert.Equal(1,await service.CountAsync("fa",CancellationToken.None));var direct=await service.PageAsync("en",1,CancellationToken.None);Assert.Single(direct.Items);Assert.Equal(S(live,"slug"),direct.Items[0].Key);Assert.True(direct.Items[0].Fa&&direct.Items[0].En);Assert.Equal(DateTimeOffset.Parse(S(published,"publishedAt")),direct.Items[0].LastModified);var page=await Read(await anon.GetAsync("/api/content/blog-sitemap/en/entries?page=1"));Assert.Equal("blog",S(page,"kind"));Assert.Single(page["items"]!.AsArray());var manifest=await Read(await anon.GetAsync("/api/content/blog-sitemap/fa"));Assert.True(manifest["isPreview"]!.GetValue<bool>());Assert.False(manifest["allowIndexing"]!.GetValue<bool>());Assert.Equal("0",S(manifest,"postCount"));foreach(var tail in new[]{"?page=0","?page=01","?page=50001","?page=1&page=2","?private=true"}){using var invalid=await anon.GetAsync("/api/content/blog-sitemap/fa/entries"+tail);Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);}
    }
    [Fact]public async Task EmptyBlogMigrationCanDowngradeAndUpgradeWithoutChangingAnExistingStaticPage()
    {
        using var staff=await Staff();var body=Content().Body;var prior=await Read(await staff.PostAsJsonAsync("/api/admin/pages/commands/"+Id(),new CmsPageWrite("Create",Slug:"retained-static-page",IsDemo:true,Content:body)));await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CmsDbContext>();var before=await db.Pages.AsNoTracking().SingleAsync();var previous=db.Database.GetMigrations().Where(x=>!x.EndsWith("_VersionedBlogPosts",StringComparison.Ordinal)).Last();await db.GetService<IMigrator>().MigrateAsync(previous);var down=await db.Pages.AsNoTracking().SingleAsync();Assert.Equal(before.Version,down.Version);Assert.Equal(before.DraftJson,down.DraftJson);Assert.Equal(before.DraftHash,down.DraftHash);await db.GetService<IMigrator>().MigrateAsync();Assert.False(db.Database.HasPendingModelChanges());var after=await db.Pages.AsNoTracking().SingleAsync();Assert.Equal(before.Version,after.Version);Assert.Equal(before.DraftJson,after.DraftJson);Assert.Equal(0,await db.BlogPosts.CountAsync());Assert.Equal(0,await db.BlogPostRevisions.CountAsync());Assert.Equal(0,await db.BlogRevisionTags.CountAsync());Assert.Equal(0,await db.BlogPostCommands.CountAsync());
    }

